      type: 'income',
      notes: 'Second note',
    };
    const receiptC = {
      id: 'rC',
      amount: 150,
      date: '2023-01-03',
      category: 'Travel',
      type: 'expense',
      notes: 'Other receipt',
    };

    await addReceipt(store, receiptA);
    await addReceipt(store, receiptB);
    await addReceipt(store, receiptC);

    // The default category should be present before rename
    await syncCategoriesWithReceipts(store);
